function applyPreferences(){({profile,equipment}=preferencesFrom(records));}
async function switchScope(next){accountEpoch++;records=[];profile=defaultProfile();equipment={};extraExercise='';timerEnd=0;lastSync=null;await openDB(next);scope=next;localStorage.setItem('form-local-scope',next);records=await allRecords();applyPreferences();lastSync=read('form-last-sync-'+scope,null);}
async function savePreferences(syncNow=true){const existing=records.find(r=>r.id==='preferences'),row={...makeRecord('preferences',dateKey(),{profile,equipment}),id:'preferences'};if(existing)Object.assign(existing,row);else records.push(row);await putMany([row]);if(auth&&syncNow)sync(false);}
async function acceptSession(session){
 if(!session?.user){auth=null;cachedAccount=null;localStorage.removeItem('form-last-account');if(scope!=='guest')await switchScope('guest');return;}
 const next='account-'+session.user.id;
 if(!/^account-[a-zA-Z0-9-]+$/.test(next))throw Error('Invalid account identifier.');
 if(scope!==next)await switchScope(next);
 auth=session;cachedAccount=session.user;localStorage.setItem('form-last-account',JSON.stringify(cachedAccount));
 if(session.canClaimLegacy&&!localStorage.getItem('form-legacy-claimed-'+session.user.id)){
  const old=await legacyRecords();if(!validateRecords(old))throw Error('Original journal failed validation; it has been retained.');
  records=mergeRecords(records,old.map(r=>({...r,updatedAt:new Date(r.updatedAt).toISOString()}))).map(r=>({...r,dirty:true}));await putMany(records);
  if(!records.some(r=>r.type==='preferences')&&(old.length||localStorage.getItem('form-profile')||localStorage.getItem('form-equipment'))){profile={...defaultProfile(),...read('form-profile',{weight:75,height:173,protein:120,pelvic:false,stage:'Foundation'}),name:session.user.name};equipment=read('form-equipment',{});await savePreferences(false);}
  localStorage.setItem('form-legacy-claimed-'+session.user.id,'true');
 }
 applyPreferences();if(!profile.name)profile.name=session.user.name;
}
async function connectCloud(){
 if(!navigator.onLine){checkingAccount=false;render();return;}
 try{if(localStorage.getItem('form-pending-signout')){await cloud('/api/auth/sign-out',{method:'POST',body:'{}'});localStorage.removeItem('form-pending-signout');}const config=await cloud('/api/config');cloudReady=!!config?.configured;if(cloudReady){cloudAccountRequired=true;localStorage.setItem('form-cloud-accounts','true');}emailReady=!!config?.emailReady;if(cloudReady)await acceptSession(await cloud('/api/account'));else auth=null;}
 catch(err){auth=null;cloudReady=false;console.warn('Cloud connection deferred:',err.message);}
 checkingAccount=false;render();if(auth)await sync(false);
}
async function sync(manual){
 if(busy)return;
 if(!navigator.onLine){if(manual)toast('Offline — records stay queued on your phone.');return;}
 if(!auth||!cloudReady){if(manual)toast('Connect and sign in under Settings.');return;}
 busy=true;const syncEpoch=accountEpoch,syncOwner=auth.user.id;const checkAccount=()=>{if(syncEpoch!==accountEpoch||auth?.user.id!==syncOwner)throw Error('Account changed; sync stopped.');};
 try{
  let remote=[],cursor='';
  do{const page=await cloud('/api/journal'+(cursor?'?after='+encodeURIComponent(cursor):''));checkAccount();if(!validateRecords(page?.records))throw Error('Cloud records failed validation.');remote.push(...page.records);const next=page.next||'';if(next&&next<=cursor)throw Error('Invalid cloud page.');cursor=next;if(remote.length>50000)throw Error('Cloud journal is too large.');}while(cursor);
  checkAccount();records=mergeRecords(records,remote);await putMany(records);applyPreferences();
  const pending=records.filter(r=>r.dirty).map(r=>({...r,updatedAt:new Date(r.updatedAt).toISOString()}));
  for(let i=0;i<pending.length;i+=100){
   checkAccount();const batch=pending.slice(i,i+100),reply=await cloud('/api/journal',{method:'POST',body:JSON.stringify(batch)});
   checkAccount();if(!validateRecords(reply?.records)||reply.records.length!==batch.length)throw Error('Cloud response failed validation.');
   const clean=[];
   for(const saved of reply.records){const sent=batch.find(r=>r.id===saved.id),current=records.find(r=>r.id===saved.id);if(!sent||!current)throw Error('Unexpected cloud record.');
    // Do not clear a new edit made while this upload was in flight.
    if(new Date(current.updatedAt).toISOString()===sent.updatedAt){Object.assign(current,saved,{dirty:false});clean.push({...current});}
   }
   await putMany(clean);
  }
  lastSync=new Date().toISOString();localStorage.setItem('form-last-sync-'+scope,JSON.stringify(lastSync));if(manual)toast('Cloud sync complete');
 }catch(err){if(err.status===401||err.status===409){auth=null;cachedAccount=null;localStorage.removeItem('form-last-account');await switchScope('guest');render();}if(manual)toast('Sync failed: '+err.message);else console.warn('Sync deferred:',err.message);}
 finally{busy=false;const status=$('.status');if(status)status.textContent=syncStatus();const cloudStatus=$('#cloud-status');if(cloudStatus)cloudStatus.textContent=syncStatus();}
}
addEventListener('storage',event=>{if(['form-local-scope','form-last-account'].includes(event.key))location.reload();});
