try{await openDB(scope);records=await allRecords();applyPreferences();render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>toast('Offline cache unavailable. Use HTTPS or localhost.'));connectCloud();}catch(err){$('#app').textContent='Local storage could not open. Enable site storage and reload; do not clear existing data without a backup.';console.error(err);}
